// Flatten DVF transactions to stable, human-readable sheet columns.
const rows = [];

for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.idMutation) continue;

  rows.push({
    json: {
      mutation_id: j.idMutation,
      date: j.dateMutation || '',
      department: j.codeDepartement || '',
      commune: j.nomCommune || '',
      postal_code: j.codePostal || '',
      address: j.adresse || '',
      property_types: Array.isArray(j.typesLocal)
        ? j.typesLocal.join('; ')
        : j.typesLocal || '',
      price_eur: j.valeurFonciere ?? '',
      price_per_m2: j.prixM2 ?? '',
      surface_m2: j.surfaceReelleBati ?? '',
      rooms: j.nombrePiecesPrincipales ?? '',
      land_m2: j.surfaceTerrain ?? '',
      latitude: j.latitude ?? '',
      longitude: j.longitude ?? '',
    },
  });
}

return rows;
